@@ -211,0 +211,9 @@
+  if (Arguments::is_valhalla_enabled()) {
+    // Flat atomic payloads may contain embedded oops. Current Valhalla code does not handle
+    // it well, missing the GC barriers. As the temporary kludge, disable compressed oops:
+    // this would make flat atomic payloads contain at most one oop, which would be treated
+    // as the single oop field.
+    log_warning(gc)("Shenandoah disables compressed oops to avoid breaking with Valhalla");
+    FLAG_SET_ERGO(UseCompressedOops, false);
+  }
+

@@ -1381,5 +1381,0 @@
-  if (do_atomic && UseShenandoahGC && vk->contains_oops()) {
-    // Atomic handling hides oops from concurrent GC, breaking it, fall back to non-atomic.
-    // FIXME: Figure out how to do this properly.
-    do_atomic = false;
-  }
@@ -1954,7 +1949,0 @@
-  if (UseShenandoahGC && _vk->contains_oops()) {
-    // Expanding to mismatched T_LONG loads would miss the barriers, expand non-atomically.
-    // FIXME: Figure out how to do this properly.
-    expand_non_atomic(igvn);
-    return;
-  }
